                    ModifiedParameters[nameof(Capabilities)] = Capabilities;
                }
                
                return true;
            case Graphic graphic:
                if (graphic != Graphic)
                {
                    Graphic = graphic;
                    ModifiedParameters[nameof(Graphic)] = Graphic;
                }
                
                return true;
            case AttachmentsOrderByInfo orderByFields:
                OrderByFields ??= [];
                if (!OrderByFields.Contains(orderByFields))
                {
                    OrderByFields = [..OrderByFields, orderByFields];
                    ModifiedParameters[nameof(OrderByFields)] = OrderByFields;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case AttachmentsCapabilities _:
                Capabilities = null;
                ModifiedParameters[nameof(Capabilities)] = Capabilities;
                return true;
            case Graphic _:
                Graphic = null;
                ModifiedParameters[nameof(Graphic)] = Graphic;
                return true;
            case AttachmentsOrderByInfo orderByFields:
                OrderByFields = OrderByFields?.Where(o => o != orderByFields).ToList();
                ModifiedParameters[nameof(OrderByFields)] = OrderByFields;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        Capabilities?.ValidateRequiredGeneratedChildren();
        Graphic?.ValidateRequiredGeneratedChildren();
        if (OrderByFields is not null)
        {
            foreach (AttachmentsOrderByInfo child in OrderByFields)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        base.ValidateRequiredGeneratedChildren();
    }
      
